head.script:
///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {void}
 * @hidden N
 */
scwin.onpageload = function() {
    try {
        $c.libRoundPanel.PanelToGroupBox(panel_Top);
        const vHeadString = "ITEM:STRING(100),NEWLIST_REQ:STRING(300),EXEM_REQ:STRING(300),CORRYN:STRING(1)";
        // dts_List.setDataHeader(); // W-Craft 주석처리 및 필요시 asis 파라미터 확인
        const parentWin = $c.frame.path("../");
        const vViewCorrYnTyp = parentWin.vViewCorrYnTyp;
        const dtsObj = parentWin.dts_CorrYn;
        txb_ISU_CD.setValue(dtsObj.getCellData(1, 'ISU_CD'));
        txb_ISU_KOR_NM.setValue(dtsObj.getCellData(1, 'ISU_KOR_NM'));
        grd_List.Redraw = false;

        // 일치항목 표시
        scwin.setListingData(dtsObj);
        grd_List.redraw = true;
        dts_List.setRowPosition(1, 0);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF08103P.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name btn_Close_onclick
 * @description 「닫기」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Close_onclick = async function() {
    try {
        await $c.win.closePopup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF08103P.btn_Close_onclick" });
    }
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name setListingData
 * @description 상장신청, 예비심사청구 데이터 표시  (신규,추가 공통)
 * @param {*} dtsObj dtsObj
 * @returns {void}
 * @hidden N
 */
scwin.setListingData = function(dtsObj) {
    const totItemCnt = 104;
    dts_List.setBroadcast(false);
    for (let j = 1; j <= totItemCnt; j++) {
        dts_List.insertRow();
    }
    dts_List.setBroadcast(true, true);
    let i = 1;
    scwin.setItem(i++, '발행회사', 'ISUR_NM', dtsObj);
    scwin.setItem(i++, '종목코드', 'ISU_CD', dtsObj);
    scwin.setItem(i++, '종목단축코드', 'ISU_SRT_CD', dtsObj);
    scwin.setItem(i++, '종목명', 'ISU_KOR_NM', dtsObj);
    scwin.setItem(i++, '종목약명', 'ISU_KOR_ABBRV', dtsObj); // 5

    scwin.setItem(i++, '종목영문명', 'ISU_ENG_NM', dtsObj);
    scwin.setItem(i++, '종목영문약명', 'ISU_ENG_ABBRV', dtsObj);
    scwin.setItemNumber(i++, '발행수량', 'ETN_ISU_QTY', dtsObj);
    scwin.setItemNumber(i++, '발행원본액', 'ISU_ORGN_VAL', dtsObj);
    scwin.setItem(i++, '기초지수명', 'IDX_NM', dtsObj); // 10

    scwin.setItem(i++, '기초지수영문명', 'IDX_ENG_NM', dtsObj);
    scwin.setItem(i++, '지수산출기관', 'IDX_CALC_INST_NM', dtsObj);
    scwin.setItem(i++, '기초시장 대', 'MKT_TP_CD_L', dtsObj);
    scwin.setItem(i++, '기초시장 중', 'MKT_TP_CD_M', dtsObj);
    scwin.setItem(i++, '기초시장 소', 'MKT_TP_CD_S', dtsObj); // 15

    scwin.setItem(i++, '기초자산 대1', 'ULY_TP_CD_L1', dtsObj);
    scwin.setItem(i++, '기초자산 중1', 'ULY_TP_CD_M1', dtsObj);
    scwin.setItem(i++, '기초자산 소1', 'ULY_TP_CD_S1', dtsObj);
    scwin.setItem(i++, '기초자산 대2', 'ULY_TP_CD_L2', dtsObj);
    scwin.setItem(i++, '기초자산 중2', 'ULY_TP_CD_M2', dtsObj); // 20

    scwin.setItem(i++, '기초자산 소2', 'ULY_TP_CD_S2', dtsObj);
    scwin.setItem(i++, '발행대행기관', 'ISU_AGNT_TP_NM', dtsObj);
    scwin.setItem(i++, '사무관리회사', 'ETN_BZ_ADM_COM_TP_NM', dtsObj);
    scwin.setItem(i++, '추적배수', 'IDX_LVRG_INVRS_TP_NM', dtsObj);
    scwin.setItem(i++, '과세유형', 'TAX_TP_NM', dtsObj); // 25

    scwin.setItemDate(i++, '만기일', 'EXP_DD', dtsObj);
    scwin.setItemDate(i++, '최종거래일', 'LSTTRD_DD', dtsObj);
    scwin.setItemDate2(i++, '만기상환가격 결정일', 'EXP_REDMPT_PRC_DECSN_STRT_DD', 'EXP_REDMPT_PRC_DECSN_END_DD', dtsObj); // from~to~
    scwin.setItemDate(i++, '만기상환금 지급일', 'EXP_REDMPT_AMT_PAY_DD', dtsObj);
    scwin.setItem(i++, '결제방법', 'LST_SETL_METHD_NM', dtsObj); // 30

    scwin.setItem(i++, '중도상환단위', 'HALFWY_REDMPT_UNIT', dtsObj);
    scwin.setItem(i++, '중도상환 신청주기', 'HALFWY_REDMPT_APPL_CYCLE_CONTN', dtsObj);
