/**
 * @method
 * @name setItem
 * @description 일반 데이터에 대해 Row 표시
 * @param {*} vIdx vIdx
 * @param {String} strNm strNm
 * @param {String} strCd strCd
 * @param {*} dtsObj dtsObj
 * @returns {void}
 * @hidden N
 */
scwin.setItem = function(vIdx, strNm, strCd, dtsObj) {
    dts_List.setCellData(vIdx, 'ITEM', strNm);
    dts_List.setCellData(vIdx, 'NEWLIST_REQ', dtsObj.getCellData(1, strCd));
    dts_List.setCellData(vIdx, 'EXEM_REQ', dtsObj.getCellData(2, strCd));
    dts_List.setCellData(vIdx, 'CORRYN', scwin.sameYn(dtsObj.getCellData(1, strCd), dtsObj.getCellData(2, strCd)));
};

/**
 * @method
 * @name setItemDate
 * @description 날짜 데이터에 대해 포맷지정 후 Row 표시
 * @param {*} vIdx vIdx
 * @param {String} strNm strNm
 * @param {String} strCd strCd
 * @param {*} dtsObj dtsObj
 * @returns {void}
 * @hidden N
 */
scwin.setItemDate = function(vIdx, strNm, strCd, dtsObj) {
    dts_List.setCellData(vIdx, 'ITEM', strNm);
    dts_List.setCellData(vIdx, 'NEWLIST_REQ', $c.stf.FormatDateEx(dtsObj.getCellData(1, strCd)));
    dts_List.setCellData(vIdx, 'EXEM_REQ', $c.stf.FormatDateEx(dtsObj.getCellData(2, strCd)));
    dts_List.setCellData(vIdx, 'CORRYN', scwin.sameYn(dtsObj.getCellData(1, strCd), dtsObj.getCellData(2, strCd)));
};

/**
 * @method
 * @name setItemDate2
 * @description 날짜 데이터에 대해 포맷지정 후 Row 표시
 * @param {*} vIdx vIdx
 * @param {String} strNm strNm
 * @param {*} strCd1 strCd1
 * @param {*} strCd2 strCd2
 * @param {*} dtsObj dtsObj
 * @returns {void}
 * @hidden N
 */
scwin.setItemDate2 = function(vIdx, strNm, strCd1, strCd2, dtsObj) {
    const date1 = $c.stf.FormatDateEx(dtsObj.getCellData(1, strCd1)) + " ~ " + $c.stf.FormatDateEx(dtsObj.getCellData(1, strCd2));
    const date2 = $c.stf.FormatDateEx(dtsObj.getCellData(2, strCd1)) + " ~ " + $c.stf.FormatDateEx(dtsObj.getCellData(2, strCd2));
    dts_List.setCellData(vIdx, 'ITEM', strNm);
    dts_List.setCellData(vIdx, 'NEWLIST_REQ', date1);
    dts_List.setCellData(vIdx, 'EXEM_REQ', date2);
    dts_List.setCellData(vIdx, 'CORRYN', scwin.sameYn(date1, date2));
};

/**
 * @method
 * @name setItemNumber
 * @description 숫자 데이터에 대해 포맷지정 후 Row 표시
 * @param {*} vIdx vIdx
 * @param {String} strNm strNm
 * @param {String} strCd strCd
 * @param {*} dtsObj dtsObj
 * @returns {void}
 * @hidden N
 */
scwin.setItemNumber = function(vIdx, strNm, strCd, dtsObj) {
    dts_List.setCellData(vIdx, 'ITEM', strNm);
    let data1 = $c.stf.FormatNumberEx(dtsObj.getCellData(1, strCd));
    let data2 = $c.stf.FormatNumberEx(dtsObj.getCellData(2, strCd));
    if (strCd === 'ISU_LIMIT') {
        // % 관련 데이터는 여기 설정
        dts_List.setCellData(vIdx, 'NEWLIST_REQ', data1 + '%');
        dts_List.setCellData(vIdx, 'EXEM_REQ', data2 + '%');
    } else {
        dts_List.setCellData(vIdx, 'NEWLIST_REQ', data1);
        dts_List.setCellData(vIdx, 'EXEM_REQ', data2);
    }
    dts_List.setCellData(vIdx, 'CORRYN', scwin.sameYn(dtsObj.getCellData(1, strCd), dtsObj.getCellData(2, strCd)));
};

/**
 * @method
 * @name setItemYyyymm
 * @description 일반 데이터에 대해 Row 표시
 * @param {*} vIdx vIdx
 * @param {String} strNm strNm
 * @param {String} strCd strCd
 * @param {*} dtsObj dtsObj
 * @returns {void}
 * @hidden N
 */
scwin.setItemYyyymm = function(vIdx, strNm, strCd, dtsObj) {
    const ym1 = dtsObj.getCellData(1, strCd);
    const ym2 = dtsObj.getCellData(2, strCd);
    let data1 = "";
    let data2 = "";
    if (ym1.length === 6) {
        data1 = ym1.substring(0, 4) + "-" + ym1.substring(4, 6);
    } else {
        data1 = ym1;
    }
    if (ym2.length === 6) {
        data2 = ym2.substring(0, 4) + "-" + ym2.substring(4, 6);
    } else {
        data2 = ym2;
    }
    dts_List.setCellData(vIdx, 'ITEM', strNm);
    dts_List.setCellData(vIdx, 'NEWLIST_REQ', data1);
    dts_List.setCellData(vIdx, 'EXEM_REQ', data2);
    dts_List.setCellData(vIdx, 'CORRYN', scwin.sameYn(ym1, ym2));
};
