/**
 * @method
 * @name sameYn
 * @description 일치여부 확인
 * @param {*} src1 src1
 * @param {*} src2 src2
 * @returns {void}
 * @hidden N
 */
scwin.sameYn = function(src1, src2) {
    if (src1 === src2) {
        return 'O';
    } else {
        return 'X';
    }
};
